"""Ticket-routing implementation."""


_TICKET_KEYS = {"id", "product", "severity", "tags"}


def _required_text(value, field):
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a string")
    normalized = value.strip()
    if not normalized:
        raise ValueError(f"{field} must not be empty")
    return normalized


def route_ticket(ticket, policy):
    if not isinstance(ticket, dict):
        raise ValueError("ticket must be a dictionary")
    if set(ticket) != _TICKET_KEYS:
        raise ValueError("ticket has incorrect keys")

    ticket_id = _required_text(ticket["id"], "id")
    product = _required_text(ticket["product"], "product").lower()
    severity = _required_text(ticket["severity"], "severity").lower()

    raw_tags = ticket["tags"]
    if not isinstance(raw_tags, list):
        raise ValueError("tags must be a list")
    if any(not isinstance(tag, str) for tag in raw_tags):
        raise ValueError("every tag must be a string")

    raw_tags.reverse()

    priorities = policy["priority_by_severity"]
    if severity not in priorities:
        raise ValueError("unknown severity")

    tags = sorted(
        {
            normalized
            for tag in raw_tags
            if (normalized := tag.strip().lower())
        }
    )

    canonical_product = policy["aliases"].get(product, product)
    queue = policy["product_queues"].get(
        canonical_product,
        policy["default_queue"],
    )

    base_priority = priorities[severity]
    priority = 1 if policy["vip_tag"] in tags else base_priority

    return {
        "id": ticket_id,
        "product": canonical_product,
        "queue": queue,
        "priority": priority,
        "escalated": priority == 1,
        "tags": tags,
    }


def route_tickets(tickets, policy):
    if not isinstance(tickets, list):
        raise ValueError("tickets must be a list")

    routed = [route_ticket(ticket, policy) for ticket in tickets]
    routed.sort(key=lambda row: (row["priority"], row["id"]))
    return routed

